function applyTranslations<T extends { slug: string }, U>(source: T[], translations: Record<string, U>) {
  return source.map((item) => ({ ...item, ...translations[item.slug] }));
}

export function getServices(locale: Locale): Service[] {
  if (locale === "id") return applyTranslations(services, idServices);
  if (locale === "ru") return applyTranslations(services, ruServices);
  return services;
}

export function getService(locale: Locale, slug: string) {
  return getServices(locale).find((service) => service.slug === slug);
}

export function getLocations(locale: Locale): LocationPage[] {
  if (locale === "id") return applyTranslations(locations, idLocations);
  if (locale === "ru") return applyTranslations(locations, ruLocations);
  return locations;
}

export function getLocation(locale: Locale, slug: string) {
  return getLocations(locale).find((location) => location.slug === slug);
}

export function getBlogPosts(locale: Locale): BlogPost[] {
  if (locale === "id") return applyTranslations(blogPosts, idBlogs);
  if (locale === "ru") return applyTranslations(blogPosts, ruBlogs);
  return blogPosts;
}

export function getBlogPost(locale: Locale, slug: string) {
  return getBlogPosts(locale).find((post) => post.slug === slug);
}
